package com.shiguangbox.app

import android.util.Base64

/**
 * V2.5.104 Yutuan turn optical-flow mesh.
 * 16 adjacent frame pairs × 2 directions × 9×9 vertices × (dx, dy).
 * Each component is a signed byte in 1/8 source-pixel units.
 */
internal object YutuanTurnFlow {
    private const val VERTICES_PER_MESH = 81
    private const val COMPONENTS_PER_VERTEX = 2

    val data: ByteArray by lazy {
        Base64.decode(FLOW_B64, Base64.NO_WRAP).also {
            check(it.size == 5184) {
                "Unexpected Yutuan turn flow data size: " + it.size
            }
        }
    }

    fun byteOffset(
        pairIndex: Int,
        directionIndex: Int,
        vertexIndex: Int
    ): Int {
        return (
            (
                pairIndex * 2 +
                    directionIndex
            ) *
                VERTICES_PER_MESH +
                vertexIndex
            ) *
            COMPONENTS_PER_VERTEX
    }

    private const val FLOW_B64 =
        ""
}
